  setIcnText($("btnRefsClear"), "i-trash", "cream", ff9(FF_L.refsClear));
  setIcnText($("btnPromptCopy"), "i-doc", "cream", ff9(FF_L.promptCopy));
  set("genEngine", ff9(FF_L.engine));
